import logging
from .ssh_process_factory import SshProcessFactory
from taf.internal.execution.base import Executor, TimeoutError

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SshExecutor(Executor):
    """
    Executor interface for SSHConnection/ProxySSHConnection.
    """

    def __init__(self, managed_ssh_connection, **kwargs):
        """
        Create an SSH executor.

        :param ManagedSshConnection managed_ssh_connection: managed SSH
                                                            connection
        """

        super(SshExecutor, self).__init__(**kwargs)
        self._managed_ssh_connection = managed_ssh_connection
        self.add_prerequisite(managed_ssh_connection)
        self._process_factories = {}
        for use_tty in (True, False):
            self._process_factories[
                use_tty] = self._create_ssh_process_factory(use_tty=use_tty)

    @property
    def password(self):
        return self._managed_ssh_connection.password

    @property
    def managed_ssh_connection(self):
        return self._managed_ssh_connection

    def raw_execute(self, command, use_tty=False):
        """
        Execute a command and wait until it finishes.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: stdout, stderr, exit status
        :rtype: bytes, bytes, int
        """
        logger.debug(
            "executing {command!r} on {host!r} as {user!r}"
            " {with_tty} terminal".format(
                host=self._managed_ssh_connection.host,
                user=self._managed_ssh_connection.user,
                command=command,
                with_tty="with" if use_tty else "without"))
        try:
            stdout, stderr, exit_status = self._raw_execute(command,
                                                            use_tty=use_tty)
        except TimeoutError:
            raise
        except Exception as exception:
            logger.debug(
                "executing failed with %r, trying to execute command again",
                exception)
            self._managed_ssh_connection.teardown(group=self._group,
                                                  force=True)
            self._managed_ssh_connection.setup(group=self._group)
            stdout, stderr, exit_status = self._raw_execute(command)
        logger.debug(
            "stdout={stdout!r}, stderr={stderr!r},"
            " exit_status={exit_status!r}".format(
                stdout=stdout,
                stderr=stderr,
                exit_status=exit_status))
        return stdout, stderr, exit_status

    def start(self, command, use_tty=False):
        """
        Start a command.

        Adds logging and optionally retry to start of command.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: process
        :rtype: Process
        """
        logger.debug(
            "starting {command!r} on {host!r} as {user!r}"
            " {with_tty} terminal".format(
                host=self._managed_ssh_connection.host,
                user=self._managed_ssh_connection.user,
                command=command,
                with_tty="with" if use_tty else "without"))
        try:
            process = self._start(command,
                                  use_tty=use_tty)
        except Exception as exception:
            logger.debug(
                "starting failed with %r, trying to start command again",
                exception)
            self._managed_ssh_connection.teardown(group=self._group,
                                                  force=True)
            self._managed_ssh_connection.setup(group=self._group)
            process = self._start(command,
                                  use_tty=use_tty)
        return process

    def _start(self, command, use_tty=False):
        """
        Start a command.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: process
        :rtype: Process
        """
        return self._process_factories[use_tty].create_process(command)

    def _create_ssh_process_factory(self, use_tty):
        return SshProcessFactory(
            managed_ssh_connection=self._managed_ssh_connection,
            use_tty=use_tty)
